package org.apache.commons.lang3;

import org.junit.Test;
import static org.junit.Assert.*;

import java.util.Locale;

public class AgentBRT_Lang_5_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // This input should be valid but is incorrectly rejected in the buggy version
        String localeStr = "en_US_";
        try {
            Locale locale = LocaleUtils.toLocale(localeStr);
            // Expecting a Locale object with language "en", country "US", and empty variant
            assertNotNull("Locale should not be null", locale);
            assertEquals("en", locale.getLanguage());
            assertEquals("US", locale.getCountry());
            assertEquals("", locale.getVariant());
        } catch (IllegalArgumentException e) {
            fail("IllegalArgumentException should not be thrown for valid input: " + localeStr);
        }
    }
}

